@aware([
    'size' => null,
    'invalid' => false,
    'fieldInvalid' => false,
    'disabled' => false,
    'controlId' => null,
    'fileUploadId' => null,
])

@props([
    'heading' => null,
    'text' => null,
    'inline' => false,
])

@php
    use App\Support\Stencil\Form\FormControlClassMap;
    use App\Support\Stencil\Interaction\InteractionStateAttributes;

    $formControl = app(FormControlClassMap::class);
    $interactionState = app(InteractionStateAttributes::class);

    $isInvalid = $invalid || $fieldInvalid;

    $resolvedHeading = filled($heading)
        ? (string) $heading
        : __('stencil-ui::messages.file_upload_heading');

    $resolvedText = filled($text) ? (string) $text : null;

    $resolvedControlId = filled($controlId)
        ? $controlId
        : (filled($fileUploadId) ? $fileUploadId : null);

    $dropzoneClasses = collect([
        'file-upload__dropzone',
        'group relative flex w-full cursor-pointer flex-col items-center justify-center gap-2 rounded-md border border-dashed border-zinc-300 bg-white px-4 text-center shadow-sm transition-colors',
        'hover:border-zinc-400 hover:bg-zinc-50',
        'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-zinc-950/10 focus-visible:ring-offset-0',
        'dark:border-zinc-700 dark:bg-zinc-950 dark:hover:border-zinc-500 dark:hover:bg-zinc-900',
        'dark:focus-visible:ring-zinc-300/20',
        'data-[dragging=true]:border-zinc-900 data-[dragging=true]:bg-zinc-50',
        'dark:data-[dragging=true]:border-zinc-50 dark:data-[dragging=true]:bg-zinc-900',
        $formControl->invalidFieldClasses(),
        $inline ? 'min-h-16 flex-row gap-3 py-3' : 'min-h-36 py-8',
        $size === 'sm' ? ($inline ? 'min-h-12 py-2' : 'min-h-28 py-6') : null,
        $isInvalid ? 'border-red-500 dark:border-red-500' : null,
        $disabled ? 'pointer-events-none cursor-not-allowed opacity-50' : null,
    ])->filter()->implode(' ');

    $dropzoneAttributes = $interactionState->apply(
        $attributes
            ->except(['heading', 'text', 'inline'])
            ->class($dropzoneClasses)
            ->merge([
                'type' => 'button',
                'data-file-upload-dropzone' => true,
                'data-dragging' => 'false',
            ]),
        ['nativeDisabled' => true],
    );

    if ($disabled) {
        $dropzoneAttributes = $dropzoneAttributes->merge(['disabled' => true]);
    }

    if ($isInvalid) {
        $dropzoneAttributes = $dropzoneAttributes->merge(['aria-invalid' => 'true']);
    }

    if (filled($resolvedControlId)) {
        $dropzoneAttributes = $dropzoneAttributes->merge([
            'aria-controls' => $resolvedControlId,
        ]);
    }

    $iconClasses = $size === 'sm' ? 'size-5' : 'size-6';
@endphp

<button {{ $dropzoneAttributes }}>
    <span class="flex size-10 items-center justify-center rounded-full bg-zinc-100 text-zinc-600 dark:bg-zinc-800 dark:text-zinc-300">
        <x-ui::icon name="upload" class="{{ $iconClasses }}" data-file-upload-dropzone-icon />
    </span>

    <span class="flex min-w-0 flex-col gap-0.5 {{ $inline ? 'items-start text-left' : 'items-center' }}">
        <x-ui::text
            :size="$size === 'sm' ? 'sm' : null"
            variant="strong"
            inline
            data-file-upload-dropzone-heading
        >{{ $resolvedHeading }}</x-ui::text>

        @if (filled($resolvedText))
            <x-ui::text
                size="sm"
                variant="subtle"
                inline
                data-file-upload-dropzone-text
            >{{ $resolvedText }}</x-ui::text>
        @endif
    </span>
</button>

@props([
    'name' => null,
    'accept' => null,
    'multiple' => false,
    'invalid' => false,
    'disabled' => false,
    'size' => null,
    'heading' => null,
    'text' => null,
    'fileUploadId' => null,
    'shortcut' => true,
])

@aware([
    'fieldInvalid' => false,
    'controlId' => null,
])

@php
    use Illuminate\Support\Str;

    $invalid = $invalid || $fieldInvalid;
    $multiple = (bool) $multiple;

    $fileUploadId = filled($fileUploadId)
        ? $fileUploadId
        : (filled($name) ? $name : 'file-upload-'.str_replace('.', '', uniqid('', true)));
    $controlId = filled($controlId) ? $controlId : $fileUploadId;

    $fieldName = $name;

    if ($multiple && filled($name) && ! Str::endsWith($name, '[]')) {
        $fieldName = $name.'[]';
    }

    $dropzoneHeading = filled($heading)
        ? (string) $heading
        : __('stencil-ui::messages.file_upload_heading');

    $dropzoneText = filled($text) ? (string) $text : null;

    $rootAttributes = $attributes
        ->except(['shortcut', 'heading', 'text', 'accept', 'multiple', 'name'])
        ->class([
            'file-upload flex min-w-0 flex-col gap-3',
            'w-full' => ! filled($attributes->get('class')),
        ])
        ->merge([
            'data-file-upload' => true,
            'data-file-upload-id' => $fileUploadId,
            'data-empty' => 'true',
        ]);

    if ($multiple) {
        $rootAttributes = $rootAttributes->merge(['data-file-upload-multiple' => 'true']);
    }

    if ($disabled) {
        $rootAttributes = $rootAttributes->merge(['data-disabled' => 'true']);
    }

    if ($invalid) {
        $rootAttributes = $rootAttributes->merge(['data-invalid' => 'true']);
    }

    $inputAttributes = new \Illuminate\View\ComponentAttributeBag([
        'type' => 'file',
        'id' => $controlId,
        'class' => 'sr-only',
        'tabindex' => '-1',
        'data-file-upload-input' => true,
    ]);

    if (filled($fieldName)) {
        $inputAttributes = $inputAttributes->merge(['name' => $fieldName]);
    }

    if (filled($accept)) {
        $inputAttributes = $inputAttributes->merge(['accept' => $accept]);
    }

    if ($multiple) {
        $inputAttributes = $inputAttributes->merge(['multiple' => true]);
    }

    if ($disabled) {
        $inputAttributes = $inputAttributes->merge(['disabled' => true]);
    }

    if ($invalid) {
        $inputAttributes = $inputAttributes->merge(['aria-invalid' => 'true']);
    }
@endphp

<div {{ $rootAttributes }}>
    <input {{ $inputAttributes }} />

    @if ($shortcut)
        @if ($slot->isEmpty())
            <x-ui::file-upload.dropzone :heading="$dropzoneHeading" :text="$dropzoneText" />
        @else
            {{ $slot }}
        @endif

        <x-ui::file-upload.list />

        <template data-file-upload-item-template>
            <x-ui::file-upload.item />
        </template>
    @else
        {{ $slot }}

        <template data-file-upload-item-template>
            <x-ui::file-upload.item />
        </template>
    @endif
</div>

@props([
    'heading' => null,
    'text' => null,
    'size' => null,
    'invalid' => false,
])

@aware([
    'disabled' => false,
])

@php
    $resolvedHeading = filled($heading) ? (string) $heading : null;
    $resolvedText = filled($text)
        ? (string) $text
        : (static function (int|float|string|null $bytes): ?string {
            if ($bytes === null || $bytes === '') {
                return null;
            }

            $value = (float) $bytes;

            if ($value < 0) {
                return null;
            }

            $units = ['B', 'KB', 'MB', 'GB', 'TB'];
            $index = 0;

            while ($value >= 1024 && $index < count($units) - 1) {
                $value /= 1024;
                $index++;
            }

            $precision = $index === 0 ? 0 : 1;

            return number_format($value, $precision).' '.$units[$index];
        })($size);

    $itemClasses = collect([
        'file-upload__item',
        'flex w-full min-w-0 items-center gap-3 rounded-md border border-zinc-200 bg-white px-3 py-2 shadow-sm',
        'dark:border-zinc-800 dark:bg-zinc-950',
        $invalid ? 'border-red-500 dark:border-red-500' : null,
    ])->filter()->implode(' ');

    $itemAttributes = $attributes
        ->except(['heading', 'text', 'size', 'invalid'])
        ->class($itemClasses)
        ->merge([
            'data-file-upload-item' => true,
        ]);

    if ($invalid) {
        $itemAttributes = $itemAttributes->merge(['data-invalid' => 'true']);
    }
@endphp

<li {{ $itemAttributes }}>
    <span class="flex size-9 shrink-0 items-center justify-center rounded-md bg-zinc-100 text-zinc-600 dark:bg-zinc-800 dark:text-zinc-300">
        <x-ui::icon name="file" class="size-4" data-file-upload-item-icon />
    </span>

    <span class="flex min-w-0 flex-1 flex-col gap-0.5">
        <span
            class="truncate text-sm font-semibold text-zinc-950 dark:text-zinc-50"
            data-file-upload-item-heading
        >{{ $resolvedHeading }}</span>

        <span
            class="truncate text-sm text-zinc-500 dark:text-zinc-400"
            data-file-upload-item-text
            @if (! filled($resolvedText)) hidden @endif
        >{{ $resolvedText }}</span>
    </span>

    <span class="flex shrink-0 items-center gap-1" data-file-upload-item-actions>
        @if (isset($actions) && ! $actions->isEmpty())
            {{ $actions }}
        @else
            <x-ui::file-upload.item.remove :disabled="$disabled" />
        @endif
    </span>
</li>

@aware([
    'disabled' => false,
])

@props([
    'disabled' => false,
])

@php
    $isDisabled = $disabled;

    $buttonClasses = collect([
        'file-upload__item-remove',
        'inline-flex size-8 shrink-0 items-center justify-center rounded-md text-zinc-500 transition-colors',
        'hover:bg-zinc-100 hover:text-zinc-900',
        'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-zinc-950/10',
        'disabled:pointer-events-none disabled:opacity-50',
        'dark:text-zinc-400 dark:hover:bg-zinc-800 dark:hover:text-zinc-50',
        'dark:focus-visible:ring-zinc-300/20',
    ])->implode(' ');

    $buttonAttributes = $attributes
        ->class($buttonClasses)
        ->merge([
            'type' => 'button',
            'data-file-upload-item-remove' => true,
            'aria-label' => __('stencil-ui::messages.file_upload_remove'),
        ]);

    if ($isDisabled) {
        $buttonAttributes = $buttonAttributes->merge(['disabled' => true]);
    }
@endphp

<button {{ $buttonAttributes }}>
    <x-ui::icon name="x" class="size-4" />
</button>

/**
 * Stencil — accessible file upload with drag-and-drop (vanilla JS, no Alpine).
 */

const FILE_UPLOAD_SELECTOR = '[data-file-upload]';
const initialized = new WeakSet();

/**
 * @param {ParentNode} root
 */
export function initFileUploads(root = document) {
    root.querySelectorAll(FILE_UPLOAD_SELECTOR).forEach((element) => {
        if (!(element instanceof HTMLElement)) {
            return;
        }

        if (initialized.has(element)) {
            return;
        }

        initialized.add(element);
        bindFileUpload(element);
    });
}

/**
 * @param {HTMLElement} root
 */
function bindFileUpload(root) {
    /** @type {HTMLInputElement | null} */
    const input = root.querySelector('[data-file-upload-input]');
    const dropzone = root.querySelector('[data-file-upload-dropzone]');
    const list = root.querySelector('[data-file-upload-list]');
    /** @type {HTMLTemplateElement | null} */
    const template = root.querySelector('template[data-file-upload-item-template]');

    if (!(input instanceof HTMLInputElement)) {
        return;
    }

    const multiple = root.hasAttribute('data-file-upload-multiple') || input.multiple;
    /** @type {File[]} */
    let files = Array.from(input.files ?? []);
    let syncing = false;

    function dispatchValueEvents(target) {
        target.dispatchEvent(new Event('input', { bubbles: true }));
        target.dispatchEvent(new Event('change', { bubbles: true }));
    }

    /**
     * @param {number} bytes
     */
    function formatBytes(bytes) {
        if (! Number.isFinite(bytes) || bytes < 0) {
            return '';
        }

        const units = ['B', 'KB', 'MB', 'GB', 'TB'];
        let value = bytes;
        let index = 0;

        while (value >= 1024 && index < units.length - 1) {
            value /= 1024;
            index += 1;
        }

        const precision = index === 0 ? 0 : 1;

        return `${value.toFixed(precision)} ${units[index]}`;
    }

    /**
     * @param {File} file
     * @param {string | null} accept
     */
    function matchesAccept(file, accept) {
        if (! accept || accept.trim() === '') {
            return true;
        }

        const tokens = accept
            .split(',')
            .map((token) => token.trim().toLowerCase())
            .filter(Boolean);

        if (tokens.length === 0) {
            return true;
        }

        const fileName = file.name.toLowerCase();
        const mime = (file.type || '').toLowerCase();

        return tokens.some((token) => {
            if (token.startsWith('.')) {
                return fileName.endsWith(token);
            }

            if (token.endsWith('/*')) {
                const prefix = token.slice(0, -1);

                return mime.startsWith(prefix);
            }

            return mime === token;
        });
    }

    /**
     * @param {FileList | File[] | null | undefined} nextFiles
     * @param {{ append?: boolean }} [options]
     */
    function setFiles(nextFiles, options = {}) {
        const incoming = Array.from(nextFiles ?? []).filter(
            (file) => file instanceof File && matchesAccept(file, input.accept),
        );

        if (multiple && options.append) {
            const existingKeys = new Set(
                files.map((file) => `${file.name}:${file.size}:${file.lastModified}`),
            );

            incoming.forEach((file) => {
                const key = `${file.name}:${file.size}:${file.lastModified}`;
                if (! existingKeys.has(key)) {
                    files.push(file);
                    existingKeys.add(key);
                }
            });
        } else if (multiple) {
            files = incoming;
        } else {
            files = incoming.slice(0, 1);
        }

        syncInput();
        renderList();
        updateEmptyState();
    }

    /**
     * @param {{ dispatch?: boolean }} [options]
     */
    function syncInput(options = {}) {
        const transfer = new DataTransfer();

        files.forEach((file) => {
            transfer.items.add(file);
        });

        syncing = true;
        input.files = transfer.files;
        syncing = false;

        if (options.dispatch !== false) {
            dispatchValueEvents(input);
        }
    }

    function updateEmptyState() {
        const empty = files.length === 0;
        root.dataset.empty = empty ? 'true' : 'false';

        if (list instanceof HTMLElement) {
            list.hidden = empty;
        }
    }

    function renderList() {
        if (!(list instanceof HTMLElement) || !(template instanceof HTMLTemplateElement)) {
            return;
        }

        list.replaceChildren();

        files.forEach((file, index) => {
            const fragment = template.content.cloneNode(true);
            const item =
                fragment instanceof DocumentFragment
                    ? fragment.querySelector('[data-file-upload-item]')
                    : null;

            if (!(item instanceof HTMLElement)) {
                return;
            }

            item.dataset.index = String(index);

            const heading = item.querySelector('[data-file-upload-item-heading]');
            if (heading instanceof HTMLElement) {
                heading.textContent = file.name;
            }

            const text = item.querySelector('[data-file-upload-item-text]');
            if (text instanceof HTMLElement) {
                const label = formatBytes(file.size);
                text.textContent = label;
                text.hidden = label === '';
            }

            const remove = item.querySelector('[data-file-upload-item-remove]');
            if (remove instanceof HTMLButtonElement) {
                const baseLabel =
                    remove.getAttribute('aria-label')?.trim() || 'Remove';
                remove.setAttribute('aria-label', `${baseLabel}: ${file.name}`);
                remove.disabled = input.disabled;
            }

            list.appendChild(fragment);
        });
    }

    /**
     * @param {number} index
     */
    function removeAt(index) {
        if (index < 0 || index >= files.length) {
            return;
        }

        files.splice(index, 1);
        syncInput();
        renderList();
        updateEmptyState();
    }

    if (dropzone instanceof HTMLElement) {
        dropzone.addEventListener('click', (event) => {
            event.preventDefault();

            if (input.disabled || root.hasAttribute('data-disabled')) {
                return;
            }

            input.click();
        });

        dropzone.addEventListener('keydown', (event) => {
            if (event.key !== 'Enter' && event.key !== ' ') {
                return;
            }

            event.preventDefault();

            if (input.disabled || root.hasAttribute('data-disabled')) {
                return;
            }

            input.click();
        });

        ['dragenter', 'dragover'].forEach((type) => {
            dropzone.addEventListener(type, (event) => {
                event.preventDefault();
                event.stopPropagation();

                if (input.disabled || root.hasAttribute('data-disabled')) {
                    return;
                }

                dropzone.dataset.dragging = 'true';
            });
        });

        ['dragleave', 'dragend'].forEach((type) => {
            dropzone.addEventListener(type, (event) => {
                event.preventDefault();
                event.stopPropagation();
                dropzone.dataset.dragging = 'false';
            });
        });

        dropzone.addEventListener('drop', (event) => {
            event.preventDefault();
            event.stopPropagation();
            dropzone.dataset.dragging = 'false';

            if (input.disabled || root.hasAttribute('data-disabled')) {
                return;
            }

            const dropped = event.dataTransfer?.files;
            setFiles(dropped, { append: multiple });
        });
    }

    input.addEventListener('change', () => {
        if (syncing || input.disabled) {
            return;
        }

        setFiles(input.files, { append: false });
    });

    if (list instanceof HTMLElement) {
        list.addEventListener('click', (event) => {
            const target =
                event.target instanceof Element
                    ? event.target.closest('[data-file-upload-item-remove]')
                    : null;

            if (!(target instanceof HTMLElement)) {
                return;
            }

            event.preventDefault();

            if (input.disabled || root.hasAttribute('data-disabled')) {
                return;
            }

            const item = target.closest('[data-file-upload-item]');
            if (!(item instanceof HTMLElement)) {
                return;
            }

            const index = Number.parseInt(item.dataset.index ?? '', 10);
            if (Number.isFinite(index)) {
                removeAt(index);
            }
        });
    }

    updateEmptyState();
    renderList();
}

document.addEventListener('stencil:mount', (event) => {
    if (!(event instanceof CustomEvent)) {
        return;
    }

    const mountRoot = event.detail?.root;

    if (!(mountRoot instanceof HTMLElement)) {
        return;
    }

    initFileUploads(mountRoot);
});

if (typeof document !== 'undefined') {
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', () => initFileUploads());
    } else {
        initFileUploads();
    }
}
